BEST_FIT_PATH = [
    (903158, 'Duality', 'Physical+Holy hybrid via Crusader Strike base - benefits from AP and Holy SP exposure. Inferred from build context, not an explicit path statement.'),
    (272624, 'Duality', 'Pure Fire school but carries both SP*0.12 and AP*0.12 per-tick coefficients - hybrid AP+SP scaling is not exclusive to named -strike schools (Primer §1, v7). Benefits from Duality itemization despite not being a hybrid-named school.'),
]

cur.executemany('''UPDATE spells SET class_origin=?, class_confidence=?, notes=?
                    WHERE id=?''',
                 [(co, conf, note, sid) for (sid, co, conf, note) in CLASS_ORIGIN])

for sid, path, note in BEST_FIT_PATH:
    cur.execute('UPDATE spells SET best_fit_path=?, notes=COALESCE(notes,"")||? WHERE id=?',
                (path, ' | PATH: ' + note, sid))

